"""Offline Codex and unretouched Chromium report, generated from V110 data."""
from pathlib import Path
import json,base64,html,hashlib,re
R=Path(__file__).resolve().parent.parent
J=lambda p:json.loads((R/p).read_text())
e=lambda s:html.escape(str(s))
C=J('report/CONTRATS_LEVEL_DESIGN_V110.json');B=J('report/browser-results-v110.json');D=J('report/operation-drive-v110.json');L=J('report/logistics-drive-v110.json');P=J('report/pursuit-drive-v110.json');H=J('report/breach-drive-v110.json');PROV=J('baseline/SOURCES_PRESERVEES_V109.json')
passed=int(re.search(r'^# pass (\d+)$',(R/'report/node-tests-v110.tap').read_text(),re.M).group(1))
assert passed==343 and all(t['ok'] for t in B['tests']) and not B['pageErrors'] and not B['consoleErrors']
assert hashlib.sha256((R/'JOUER_ALIENS_V110.html').read_bytes()).hexdigest()==B['htmlSha256']
STYLE='''*{box-sizing:border-box}html{scroll-behavior:smooth;color-scheme:dark}body{margin:0;background:#0b1514;color:#d4dfd1;font:16px/1.8 Arial,Helvetica,sans-serif}main{max-width:1160px;padding:42px 32px 84px;margin:auto}a{color:#cee1b3;text-underline-offset:4px}h1{font:400 clamp(36px,5vw,63px)/1.13 Georgia,serif;letter-spacing:-.025em;color:#e1e9d8;margin:20px 0 24px}h2{font:400 29px/1.3 Georgia,serif;color:#cadcba;margin:44px 0 18px;padding-top:26px;border-top:1px solid #405d4d}h3{font-size:20px;line-height:1.35;font-weight:500;color:#d1dcc6;margin:26px 0 10px}p{max-width:96ch}.eyebrow{font:11px/1.45 monospace;letter-spacing:.25em;color:#9baea6;text-transform:uppercase}.lead{font-size:20px;line-height:1.65;max-width:940px}.callout{padding:18px 24px;margin:27px 0;background:#1d342b;border-left:3px solid #b6a674;color:#d0d9bc}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:28px 0}.metric{padding:20px;border:1px solid #3a564a;background:linear-gradient(135deg,#203931,#11231d)}.metric strong{font:400 33px/1.2 Georgia,serif;color:#e0d9ad;display:block}.metric small{font-size:12px;color:#adc3b0}nav{display:flex;flex-wrap:wrap;gap:16px 25px;border-bottom:1px solid #334c3e;padding:12px 0 20px}table{width:100%;border-collapse:collapse;margin:22px 0;font-size:12px;line-height:1.5}th,td{text-align:left;vertical-align:top;padding:11px 13px;border:1px solid #3e594b}th{background:#263e32;font-weight:600;color:#dfdfc4}tr:nth-child(even){background:#192d2570}.small,figcaption{font-size:13px;line-height:1.65;color:#a7b8a4}figure{margin:30px 0 42px}img{width:100%;height:auto;display:block;background:#07120e;border:1px solid #536a55}figcaption{margin-top:10px}code,pre,.mono{font:12px/1.6 ui-monospace,Consolas,monospace;overflow-wrap:anywhere}pre{white-space:pre-wrap;background:#07120e;border:1px solid #3d5846;padding:20px}.room{padding:28px;margin:28px 0;border:1px solid #3d5b4a;background:linear-gradient(145deg,#172b2370,#0c1a1480)}.room.new{border-color:#577f86;background:linear-gradient(140deg,#17313a80,#101d1b80)}.room h2{padding-top:0;border:none;margin-top:12px}.diagram{display:block;width:100%;height:auto;background:#0a1b15;border:1px solid #3c5e4c;margin:20px 0}details{margin:15px 0;padding:17px 20px;border:1px solid #385246;background:#13271d}summary{cursor:pointer;color:#d3ddbc;font-size:17px;line-height:1.4}.room summary{font-size:14px}input{width:100%;padding:16px 19px;border:1px solid #738975;background:#13271f;color:#e0e8d9;font:15px Arial}input:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid #d5ddb3;outline-offset:4px}.hidden{display:none!important}.chip{display:inline-block;margin:2px 6px 2px 0;padding:4px 9px;border:1px solid #526952;background:#294134;color:#d1daba;font:11px/1.4 monospace}.two{display:grid;grid-template-columns:1fr 1fr;gap:20px}.rule-index{color:#789284;font:12px monospace;margin-right:10px}@media(max-width:740px){main{padding:25px 16px}.metrics{grid-template-columns:1fr 1fr}.room{padding:15px}.two{grid-template-columns:1fr}table{display:block;overflow-x:auto}.lead{font-size:17px}h2{font-size:25px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{body{background:white;color:#222}h1,h2,h3{color:#222}main{padding:0}.room,figure,tr{break-inside:avoid}nav,input{display:none}.room{break-before:page}img{max-height:160mm;object-fit:contain}.callout{background:#f4f4ef;color:#222}}'''

def page(title,body,script=''):
 return f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Aliens V110 : tenue des sas, plans et captures du jeu exécuté"><title>{e(title)}</title><style>{STYLE}</style></head><body><main>{body}</main>{script}</body></html>'

def table(headers,rows):
 return '<table><thead><tr>'+''.join('<th>'+e(v)+'</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'

def metrics(rows):return '<div class="metrics">'+''.join('<div class="metric"><strong>'+e(v)+'</strong><small>'+e(t)+'</small></div>' for v,t in rows)+'</div>'

def diagram(room):
 w,d=room['width'],room['depth'];out=[f'<svg class="diagram" viewBox="-25 -30 {w+50} {d+115}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Plan de géométrie {e(room["title"])}"><rect width="{w}" height="{d}" fill="#142c23" stroke="#67856d"/>']
 for b in room['solids']:
  fill='#729fa5' if b.get('material')=='glass' else '#566c5b';out.append(f'<rect x="{b["x"]}" y="{b["z"]}" width="{b["w"]}" height="{b["d"]}" fill="{fill}" stroke="#a0b4a0" fill-opacity=".6"/><text x="{b["x"]+3}" y="{b["z"]+13}" fill="#e2ead1" font-size="10">{e(b["id"])}</text>')
 for b in room['doors']+room['hatches']:
  out.append(f'<rect x="{b["x"]}" y="{b["z"]}" width="{b["w"]}" height="{b["d"]}" fill="#b3934944" stroke="#e5c779" stroke-width="2" stroke-dasharray="4 3"/>')
 for prop in room['props']:out.append(f'<circle cx="{prop["x"]}" cy="{prop["z"]}" r="5" fill="#b5cba0"/>')
 for x in room['exits']:
  out.append(f'<circle cx="{x["x"]}" cy="{x["z"]}" r="12" fill="none" stroke="#a4d5b0" stroke-width="3"/><line x1="{x["x"]}" y1="{x["z"]}" x2="{x["arrival"]["x"]}" y2="{x["arrival"]["z"]}" stroke="#b1c797" stroke-dasharray="4 5"/><circle cx="{x["arrival"]["x"]}" cy="{x["arrival"]["z"]}" r="5" fill="#dadbb5"/>')
 for r in [x for x in C['resources']+C['alarms']+[C['engineeringStock']] if x['roomId']==room['id']]:
  out.append(f'<circle cx="{r["x"]}" cy="{r["z"]}" r="{r["reach"]}" fill="none" stroke="#e4cb76" stroke-dasharray="3 5"/><text x="{r["x"]-30}" y="{r["z"]-29}" fill="#f0d586" font-size="11">{e(r["id"])}</text>')
  if r.get('emitter'):out.append(f'<circle cx="{r["emitter"]["x"]}" cy="{r["emitter"]["z"]}" r="6" fill="#e09361"/>')
 out.append(f'<text x="8" y="{d+27}" fill="#c4cdb6" font-size="13">Schéma issu des données — pleins : collisions · ambre : portes/sas · cercle pointillé : portée de travail</text><text x="8" y="{d+53}" fill="#97b39e" font-size="12">Ce plan de conception n’est pas une capture du rendu. La carte en jeu ne montre ni ennemis ni stocks cachés.</text></svg>');return ''.join(out)

RULES=[
('Deux lieux, un détour réellement facultatif','La galerie et la réserve créent la boucle Operations → Galerie logistique → Réserve technique → Maintenance. Les cinq objectifs ordonnés de Repli sur Operations restent inchangés. La liaison médicale de service et la route directe restent praticables. La reconnaissance du détour est un bilan local : elle ne remplace aucune mission historique.'),
('Un stock est un objet du niveau','Chaque réserve a un identifiant, une emprise métallique au sol, un point de travail, une portée et une quantité finie. La desserte bloque corps et balles. L’interaction ignore uniquement son propre support dans le rayon de travail, jamais les cloisons ou les autres meubles. Les scellés prennent 1,05 seconde à ouvrir ; les réserves ne sont créditées qu’au bout du geste.'),
('Conservation exacte des ressources','Les trois stocks apportent trois lots personnels, deux trousses et une cartouche pour sentinelle. Inventaire restant + ressources dépensées doit toujours correspondre à la somme des stocks effectivement ouverts. Aucun objet n’est gagné à l’entrée d’une pièce, à l’inspection suivante ou au chargement. Une caisse déjà récupérée reste ouverte et vide.'),
('Soigner un acteur présent','Le soin dure 1,6 seconde, exige un allié vivant et proche, et rend au maximum 30 PV, sans dépasser 100. Il consomme une trousse seulement à son achèvement. Newt peut être soignée une fois recrutée ; elle ne reçoit pas d’arme. Aucun soin ne ressuscite un acteur, ne répare une tourelle ou ne cible un équipier dans une autre pièce.'),
('Ravitailler ne signifie pas recharger gratuitement','Un lot personnel donne 18 cartouches en 0,85 seconde, avec plafond de 96. Une cartouche de sentinelle ajoute 40 coups en 1,35 seconde, plafond de 120. Le transfert n’a lieu que si un manque existe et si l’objet de réserve correspondant est réellement disponible. La sentinelle conserve ses tirs à ligne dégagée et n’a aucun rechargement automatique.'),
('Le travail reste exposé','Marcher, tirer, quitter la portée, subir un impact ou changer les données de la cible interrompt le geste. Le joueur et la cible ne doivent pas se déplacer ou tirer pendant l’assistance ; seul l’allié aidé est momentanément immobilisé, pas le reste de l’escouade. Un nouvel ordre à cet allié annule le soin. Les contacts continuent de simuler leurs attaques ; la pause seule suspend globalement le temps.'),
('Reprendre au milieu d’un soin','L’export contient durée, temps effectué, positions de départ, santé et munitions observées. L’import vérifie ces données contre l’état physique restauré et reprend en pause. Un fichier ne peut pas revendiquer une cible absente, modifier une durée, accorder des ressources inexpliquées ou soigner pendant le chargement. L’action interrompue ne consomme pas sa trousse.'),
('Une sirène attire, elle ne crée pas de menace','La commande de diagnostic demande 0,65 seconde, émet pendant 8 secondes et impose un délai total de 20 secondes avant réactivation. Les impulsions suivent le système sonore V108 : chemins libres, atténuation aux passages et limite de deux liaisons. Aucun Xéno n’est créé, tué ou téléporté par le diagnostic. Les contacts encore vivants peuvent chercher le dernier son et entrer par un seuil réellement accessible.'),
('Placer correctement la source sonore','Le point de commande peut appartenir au meuble ; l’émetteur de son doit être hors de son volume obstrué. Dans la réserve, la commande est à (1214, 238), l’émetteur à (1170, 238). Un émetteur enfoui dans le cabinet empêchait initialement la propagation par chemin : la géométrie a été corrigée, pas le filtre acoustique contourné.'),
('Fermer derrière l’équipe a une conséquence','Les huit liaisons sont réciproques et instancient seize volumes de seuil. Leur fermeture coupe corps, vue, tirs et trajets sonores. Un acteur présent ou en transit interdit l’écrasement du seuil. Les nouveaux raccords ne bénéficient d’aucune exemption : les trois Marines, Newt et les créatures doivent atteindre leur accès et attendre une arrivée libre.'),
('Conserver la menace et les pertes','Onze ennemis et une sentinelle existent dans le catalogue ; dix ennemis sont dans le réseau de l’opération, le Sulaco reste isolé en inspection. Une créature qui traverse conserve identité et vie. Quitter une pièce ne retire pas un ennemi de la condition de défense. Les blessures et munitions suivent le même registre d’équipe à travers les sept lieux.'),
('Respecter le vocabulaire des lieux','La galerie utilise métal bleuté, rideau de fret, palettes, tracteur stationné et portiques. La réserve utilise comptoir médical, casiers, batteries et diagnostic ambre. Leur plan ne doit pas être copié sans fonction : le passage central ouvre une ligne de tir, les grandes masses offrent un contournement et les stocks sont placés après l’exposition, pas sur le point d’arrivée.'),
('Un appui graphique doit correspondre à un appui physique','Le tracteur est ancré au volume parked-tug, sans dessin posé artificiellement au-dessus d’une autre caisse. Les chariots de secours et de munitions utilisent leur bodyId. Le moniteur de réserve et la caisse sur palette ont une élévation explicite reliée à leur support. Les objets proches ne dérivent pas avec la caméra ; la parallaxe est réservée aux éléments lointains.'),
('Rendre lisible sans cacher le combat','La silhouette, les pieds, le volume de tir et l’emprise au sol utilisent les mêmes coordonnées. Les premiers plans proches sont atténués s’ils cachent un allié, mais conservent leurs collisions. Les scellés ouverts montrent un couvercle et un contenu vide ; la sirène montre un cycle puis un délai. Les textures et personnages sont encore procéduraux, pas des sprites finalisés.'),
('HUD et carte hors du terrain','Santé, munitions, détecteur, ressources et ordres restent dans des bandes hors canvas. La carte et les archives remplacent temporairement le terrain. La carte ne dévoile que les lieux visités : ni positions ennemies, ni santé adverse, ni réserves non découvertes. Les contrôles 844 × 390 et 390 × 844 sont émulés ; aucun appareil physique n’est certifié.'),
('Migrer sans transformer l’ancien parcours','V108 est validée par son propre importeur avant migration. Les pièces et membres hérités gardent vies, ressources, ordres et progression. Les deux lieux supplémentaires sont initialisés au temps courant, les nouveaux contacts sont sans mémoire et les nouvelles liaisons sont ouvertes. Aucune réserve n’est offerte. V107 et V106 passent par leurs validateurs antérieurs ; V106 reste une inspection.'),
('Définition d’un lieu prêt à raccorder','Vérifier tous les seuils avec le gabarit du groupe, tirer contre chaque volume, contourner les props, interrompre une assistance, revenir après collecte, importer à mi-geste, déclencher la sirène portes ouvertes puis isolées, et terminer le repli. Les graphismes seuls ne prouvent ni la géométrie ni le raccord natif. La fusion au moteur Tantalus doit être testée sur ses sources exactes.'),
]

notes={
'v109-logistics':('QUAI / NOUVEAU','Galerie sous scellés','Le rideau coupe le couloir central. Le tracteur stationné occupe son vrai gabarit au nord et la palette laisse un passage par le sud. La réserve de munitions est au-delà du contact du quai : l’approche doit être nettoyée ou couverte avant les 1,05 seconde de travail.'),
'v109-reserve':('SECOURS / NOUVEAU','Choisir le bon moment','Le premier berceau contient la cartouche de sentinelle ; les trousses sont derrière la cloison. La sirène se trouve côté maintenance pour offrir une option de détour, mais l’accès nord ouvert permet aussi l’arrivée d’un contact. La portée de commande et le point émetteur sont distincts.'),
'v107-operations':('CARREFOUR','Une branche de plus, pas un radar','L’accès sud mène maintenant à la galerie. Le meuble central conserve son rôle de couverture et de coupure visuelle. Un groupe doit encore rejoindre le seuil : Rallier ne téléporte personne. L’accès à la logistique ne modifie pas les conditions de Newt ni de défense.'),
'v107-service':('MAINTENANCE','Le relais au bout de la boucle','La réserve rejoint la maintenance par le nord. Aucun obstacle hérité n’a été déplacé pour inventer un raccord ; l’arrivée libre est vérifiée contre la pompe et le transformateur. La commande du relais garde son rôle de jalon local, sans devenir un réseau électrique général.'),
'v106-hadley':('INSERTION','Départ conservé','Porte résidentielle, contacts et raccord Operations sont conservés. Les stocks commencent à zéro. Les créatures peuvent suivre le groupe après le départ si elles possèdent un indice et une route ouverte.'),
'v106-medlab':('ESCORTE','Secourir avant d’assister','Le vitrage laisse voir sans autoriser les tirs au travers. Newt reste protégée avant recrutement, puis doit rejoindre le groupe. Une trousse peut la soigner à portée ; le ravitaillement ne peut jamais lui donner de cartouches.'),
'v106-sentry':('DÉFENSE','Quarante coups, pas une réserve infinie','La cartouche de réserve se transfère à proximité de la sentinelle vivante. Il faut trouver une fenêtre de 1,35 seconde sans déplacement de cible ni variation de ses munitions. Un tir de la sentinelle pendant le geste l’interrompt ; son ravitaillement est une action protégée, pas un bouton instantané au milieu de la rafale.'),
'v106-sulaco':('INSPECTION','Final natif préservé','Cette pièce reste inspectable seule. Elle n’est pas raccordée à Repli sur Operations. La représentation de la Reine et du loader n’est pas un nouveau final filmique ; la commande du sas reste réservée au système historique non fusionné ici.')}
# Reframe inherited doctrine without re-labelling old geometry as new content.
RULES[0]=('Conserver le parcours, changer la tenue des accès','Les huit lieux et les cinq objectifs de Repli sur Operations sont conservés. Sept lieux forment le réseau jouable ; le Sulaco reste une inspection séparée. V110 ne rajoute ni mission obligatoire, ni ennemi, ni couloir. Renforcer un accès est une décision facultative qui consomme une réserve et peut retarder aussi le retour du groupe.')
RULES[9]=('Fermer n’est plus une garantie illimitée','Un sas fermé continue à couper corps, vue et tirs. Un Warrior ne peut le forcer que s’il possède un souvenir valable situé au-delà, ne trouve pas de route ouverte et a réellement atteint la face du battant. Une porte fermée reste inconnue comme cible lorsqu’aucun indice ne guide la créature : pas d’omniscience ni de vague créée par la fermeture.')
RULES[14]=('Protéger le terrain sur petit écran','Le HUD, le détecteur, les réserves, le génie et les ordres restent hors canvas. À moins de 460 pixels de haut en paysage, Réserves et Génie partagent un emplacement avec deux boutons de commutation ; O/U/J exposent le bon volet. En portrait, les bandes restent accessibles. La carte ne montre aucune identité, position ou santé ennemie. Les formats testés sont émulés, pas des téléphones certifiés.')
RULES[15]=('Migrer V109 sans cadeaux','Le validateur V109 doit d’abord accepter la partie source. Les pièces, membres, vies, chargeurs, stocks et objectifs restent identiques. Les nouvelles structures commencent intactes, la réserve de plaques à zéro et la pression ennemie sans préparation en cours. Une visite de maintenance antérieure ne vaut pas collecte de renforts. V108 et V107 passent par leurs vrais validateurs ; V106 reste une inspection.')
RULES[16]=('Recette d’un lieu et de son seuil','Vérifier les deux faces avec les gabarits, corps et tirs, fermer devant la piste d’un contact, interrompre une soudure, observer un impact annoncé, reconstruire uniquement à seuil libre, recharger à mi-geste puis finir le repli. Les images seules ne prouvent pas la géométrie. Le raccord aux 64 salles Tantalus exige leurs sources exactes et une recette dédiée.')
RULES.extend([
 ('Un battant commun à deux pièces','Les huit liaisons ont chacune une structure unique : intégrité 100, renfort de 0 à 72, état de brèche et compte d’impacts. Les seize volumes de seuil sont dérivés de cet état partagé. Quand un battant cède, ses deux volumes disparaissent simultanément du chemin des corps, de la vision, des rayons et du graphe de passage.'),
 ('Trois plaques, réellement récupérées','La caisse service-crate est sur la table cable-rack de maintenance. Son point est (837,314), avec 82 unités de portée ; l’approche utilisée par le pilote est (793,314). Seul son support peut être ignoré dans le rayon d’interaction. E prépare la collecte pendant 1,1 seconde, puis crédite exactement trois plaques. Le couvercle reste ouvert et la caisse vide au retour.'),
 ('Souder bloque aussi le joueur','O demande un sas fermé, intact et sans renfort. Après 1,8 seconde immobile, une plaque est dépensée et fournit 72 points de protection. R ne peut pas rouvrir ce sas soudé. Un deuxième renfort est refusé ; cette action n’empile pas les plaques pour créer un mur infini.'),
 ('Découper est un engagement','U découpe le renfort pendant 1,4 seconde puis ouvre le sas. Il ne demande pas de nouvelle plaque et n’en restitue pas. Le renfort et la collision restent en place jusqu’à la fin. Un déplacement, tir ou impact annule la découpe ; le groupe doit toujours effectuer son franchissement normal.'),
 ('Réparer seulement un seuil libre','J reconstitue un battant endommagé ou arraché pendant 2,2 secondes. Il consomme une plaque à la fin, remet 100 d’intégrité, supprime tout renfort résiduel et ferme le sas. Les deux faces et les réservations de franchissement sont testées au début et avant achèvement. Aucun acteur ne peut être enfermé dans le nouveau volume.'),
 ('Pression physique, pas une horloge de destruction','Seuls les Warriors préparent la brèche ; les Facehuggers ne percent pas les battants. Le Warrior atteint sa face de travail, annonce 0,8 seconde, frappe pour 28, puis récupère 0,7 seconde. Le renfort absorbe les chocs avant l’intégrité. À pleine résistance et sans réparation, il faut quatre impacts sans renfort et sept avec une plaque entière. Ces comptes ne sont pas des secondes de survie garanties.'),
 ('Interrompre sans ressources fantômes','Bouger, tirer, perdre des PV, perdre la portée ou subir une variation de structure annule le geste. Aucun débit n’a lieu avant la fin. La pause fige temps et IA ; elle n’accomplit pas le travail. Une préparation ancienne est abandonnée si son sas s’ouvre ou est reconstitué : un coup engagé contre un ancien panneau ne touche pas magiquement le nouveau.'),
 ('Une brèche doit rester visible et franchissable','Le rendu lit les mêmes états : croix soudée, rayures sur les battants touchés, montants déformés et débris non bloquants après rupture. Un battant arraché ne se referme pas avec R ; J est requis. Aucun sprite de porte intacte ni collision invisible ne doit rester devant un passage bréché. Les portes intérieures narratives et le final du Sulaco sont exclus de ce système.'),
 ('Reprendre une pression sans la réinitialiser','Schéma 110 : intégrité et renfort, source des plaques, total dépensé, gestes et attaques préparées sont validés avant toute mutation. Une reprise reste en pause. L’ennemi conserve sa résidence, sa vie et la piste qui justifie l’attaque. Les propres coups du frappeur ne remplacent pas sa mémoire par un son qu’il vient de produire ; les autres contacts peuvent néanmoins les entendre.'),
])
notes['v109-logistics']=('FRET / HÉRITÉ','Le détour garde sa fonction','Les lots personnels restent finis. Le sas d’Operations peut être isolé, mais un contact ayant suivi une piste peut désormais revenir forcer son battant. Le rideau de fret intérieur garde sa logique précédente ; il n’est pas devenu une cible de brèche V110.')
notes['v109-reserve']=('SECOURS / HÉRITÉ','Attirer sans créer de contacts','Trousses, cartouche sentinelle et sirène sont conservées. Une diversion et un sas soudé agissent sur les mêmes créatures existantes. Aucun soin ou diagnostic ne restaure une plaque. La liaison maintenance permet d’obtenir le matériel de génie sans revenir par Operations.')
notes['v107-operations']=('CARREFOUR / TENUE','Le sas résidentiel devient une décision','Le contrôle ouest est la cible de la recette principale : fermeture après fuite, quatre impacts, franchissement ennemi, récupération des plaques, réfection, soudure puis découpe. Le meuble central permet de rester hors de la gorge. Les réservations d’arrivée empêchent d’empiler les alliés dans le seuil.')
notes['v107-service']=('GÉNIE / CAISSE FINIE','Chercher les renforts sur un support réel','La caisse sur la table de câblage reçoit les trois plaques de génie. L’emprise cable-rack et la géométrie héritée restent identiques. On l’atteint après le relais ; ouvrir la caisse exige 1,1 seconde à portée. Les plaques ne sont pas données au seul fait d’entrer dans la salle.')
notes['v106-hadley']=('INSERTION','La fuite ne fait pas disparaître la piste','Le premier parcours de brèche laisse les contacts résidentiels vivants et rejoint Operations. Ils atteignent le sas fermé en conservant leurs identités. Aucune injection de créature, dégât ou mémoire n’est nécessaire pour obtenir la pression testée.')
notes['v106-medlab']=('ESCORTE','Newt attend les vrais passages','Les vitrages continuent à séparer vue et tirs. Newt n’est pas un outil de génie ni une combattante ; elle suit les ouvertures disponibles avec les autres alliés. La décision de souder un sas peut imposer une découpe avant le retour vers Operations.')
notes['v106-sentry']=('DÉFENSE','Tenir sans ressource infinie','La tourelle conserve ses propres munitions, ses rayons et son ravitaillement limité. Le sas de liaison peut être réparé ou renforcé, mais le rideau intérieur de défense reste un mécanisme distinct. Sortir un ennemi du couloir ne le retire pas du registre de menace de la défense.')
# Codex combines rules, common systems, and room-specific coordinate contracts.
body='<p class="eyebrow">ALIENS / TANTALUS — carnet de conception V110</p><h1>Tenir les accès.<br>Sans figer le monde.</h1><p class="lead">Huit lieux conservés, huit battants partagés, trois plaques finies. Le génie prolonge la poursuite : il ne crée ni ennemis ni objectifs supplémentaires.</p>'+metrics([(8,'fiches de lieux'),(8,'sas structuraux réciproques'),(3,'plaques récupérables'),(len(RULES),'règles de conception')])
body+='<nav><a href="JOUER_ALIENS_V110.html">Jouer</a><a href="RAPPORT_ILLUSTRE_V110.html">Captures</a><a href="#regles">Règles</a><a href="#lieux">Plans</a></nav><div class="callout">Ce Codex décrit la branche autonome livrée, pas la fusion dans les 64 salles natives. Les schémas ci-dessous viennent des mêmes volumes que le module ; ce sont des plans de conception, pas des captures d’écran.</div>'
body+='<h2 id="regles">Les règles à conserver</h2>'
md=['# CODEX LEVEL DESIGN — ALIENS V110 / Tenir les accès','Branche autonome V109 poursuivie ; aucun raccord natif ni nouveau final.','## Règles de conception']
for i,(title,text) in enumerate(RULES,1):
 body+=f'<details class="design-rule"><summary><span class="rule-index">{i:02}</span>{e(title)}</summary><p>{e(text)}</p></details>'
 md += [f'### {i:02} — {title}',text]
body+='<h2>Gestes et résistance</h2>'+table(['Commande','Durée','Condition','Résultat'],[['E / caisse technique','1,1 s','Maintenance, caisse non vidée','Trois plaques, une fois'],['R / manœuvre','0,88 s à ouvrir','Sas non soudé ; ne ferme pas une brèche','Collision partagée'],['O / renforcer','1,8 s','Intégrité 100, fermé, non renforcé','1 plaque → 72 de renfort'],['U / découper','1,4 s','Renfort présent','Ouvre ; aucune plaque rendue'],['J / refaire','2,2 s','Structure touchée ; deux faces libres','1 plaque → 100, sas fermé'],['Warrior / frapper','0,8 + 0,7 s','Piste valide, face atteinte','28 dégâts ; renfort en premier']])
body+='<h2 id="lieux">Les huit lieux</h2><input id="filter" type="search" placeholder="Filtrer : maintenance, renfort, sentinelle, escorte…" aria-label="Filtrer les fiches de lieu"><p id="filter-note" class="small">8 fiches disponibles</p>'
for room in C['rooms']:
 tag,title,text=notes[room['id']];stocks=[x for x in C['resources'] if x['roomId']==room['id']];alarms=[x for x in C['alarms'] if x['roomId']==room['id']];genie=room['id']==C['engineeringStock']['roomId'];search=' '.join([room['title'],tag,title,text,'renfort plaques caisse' if genie else '']).lower()
 body+=f'<article class="room" id="{e(room["id"])}" data-search="{e(search)}"><p class="eyebrow">{e(tag)} · {e(room["id"])}</p><h2>{e(room["title"])}</h2><h3>{e(title)}</h3><p>{e(text)}</p><p class="small">{e(room["subtitle"])}</p>'+diagram(room)
 body+=table(['Raccord','Seuil x,z','Arrivée x,z','Liaison commune'],[[x['label'],f'{x["x"]},{x["z"]}',f'{x["arrival"]["x"]},{x["arrival"]["z"]}',x['linkId']] for x in room['exits']]) if room['exits'] else '<p>Inspection isolée ; aucun raccord avec l’opération.</p>'
 if room['exits']:body+='<p class="small">Chacun de ces seuils partage un battant 100 + renfort 0..72 avec sa face opposée. R n’ouvre pas un renfort. J exige les deux extrémités libres ; aucune réfection locale ne peut ignorer la pièce hors champ.</p>'
 if stocks:body+=table(['Stock','Point / portée','Emprise','Quantité unique'],[[x['name'],f'{x["x"]},{x["z"]} / {x["reach"]}',x['bodyId'],str(x['grant'])] for x in stocks])
 if genie:
  g=C['engineeringStock'];body+='<div class="callout"><strong>Kit de génie ajouté sur la caisse existante</strong><p>Point de travail (837,314), portée 82, support cable-rack, approche libre vérifiée. Trois plaques après 1,1 seconde, rien avant l’achèvement. Les états ouvert/vide sont persistants.</p></div>'
 if alarms:body+=table(['Diagnostic','Commande','Émetteur libre'],[[x['name'],f'{x["x"]},{x["z"]}',f'{x["emitter"]["x"]},{x["emitter"]["z"]}'] for x in alarms])
 body+='<details><summary>Volumes physiques et seuils dérivés</summary>'+table(['ID','x / z','w / d / h','Matériau'],[[v['id'],f'{v["x"]}/{v["z"]}',f'{v["w"]}/{v["d"]}/{v.get("h","—")}',v.get('material','structure')] for v in room['solids']+room['doors']+room['hatches']])+'</details><details><summary>Props et supports</summary>'+table(['Objet','Support nommé','Référence','Élévation'],[[p['id']+' / '+p['type'],p.get('support','—'),p.get('bodyId',p.get('supportId','mur / sol')),p.get('elevation',0)] for p in room['props']])+'</details></article>'
 md += ['## '+room['title'],title+' — '+text,'### Accès']+[f'- {x["label"]} : seuil ({x["x"]},{x["z"]}), arrivée ({x["arrival"]["x"]},{x["arrival"]["z"]}), battant partagé {x["linkId"]}.' for x in room['exits']]
 md += ['### Emprises et battants']+[f'- {v["id"]} : x={v["x"]}, z={v["z"]}, w={v["w"]}, d={v["d"]}, h={v.get("h","—")}.' for v in room['solids']+room['doors']+room['hatches']]
 md += ['### Supports']+[f'- {p["id"]} : {p.get("support","—")}, référence={p.get("bodyId",p.get("supportId","mur / sol"))}, élévation={p.get("elevation",0)}.' for p in room['props']]
 if genie:md += ['### Kit de génie',json.dumps(C['engineeringStock'],ensure_ascii=False)]
body+='<h2>Contrat et validation</h2><p class="mono">'+e(C['version'])+' · empreinte '+e(C['contract'])+'</p><p>47 emprises fixes, 9 portes intérieures, 42 props et 16 volumes de seuil ; aucune nouvelle géométrie statique. Trois plaques ajoutées comme contenu d’une caisse existante, pas comme trois sprites. Les contrôles et la durée des gestes sont exportés avec le contrat.</p>'
filter_js='''<script>const f=document.querySelector('#filter'),cards=[...document.querySelectorAll('.room')];f.addEventListener('input',()=>{const q=f.value.toLocaleLowerCase('fr').trim();let n=0;for(const c of cards){const yes=c.dataset.search.includes(q);c.classList.toggle('hidden',!yes);if(yes)n++;}document.querySelector('#filter-note').textContent=n+' lieu(x) correspondant(s)';});</script>'''
(R/'CODEX_LEVEL_DESIGN_V110.html').write_text(page('Aliens V110 — Codex Tenir les accès',body,filter_js));(R/'CODEX_LEVEL_DESIGN_V110.md').write_text('\n\n'.join(md)+'\n')
# Provenance-bound, byte-for-byte image embedding.
selection=[('00_menu.png','Une opération conservée, un accès de génie supplémentaire'),('25_battant_endommage.png','Le sas a réellement encaissé un premier impact'),('26_breche_sous_pression.png','La poursuite ouvre sa propre route'),('27_plaques_recuperees.png','La caisse de maintenance ne fournit que trois plaques'),('28_refection_en_cours.png','Réparer demande un seuil libre et du temps'),('29_soudure_chalumeau.png','Une soudure commencée par clic dans le jeu'),('30_sas_soude.png','Le renfort protège et interdit aussi une ouverture ordinaire'),('31_decoupe_en_cours.png','Découper pour rouvrir, sans récupérer la plaque'),('32_repli_genie.png','Fin d’opération avec les dépenses conservées'),('21_sentinel_ravitaillement.png','La logistique précédente reste active'),('33_genie_844x390.png','Le génie sur écran court, sans masquer le terrain'),('17_galerie_stock_ouvert.png','La boucle logistique et ses caisses vides sont conservées')]
byfile={c['file']:c for c in B['captures']}
def picture(c,title):
 raw=(R/'report/captures-v110'/c['file']).read_bytes();assert raw[:8]==b'\x89PNG\r\n\x1a\n'
 return f'<figure><h3>{e(title)}</h3><img loading="lazy" src="data:image/png;base64,{base64.b64encode(raw).decode()}" alt="{e(title)} — capture du jeu autonome V110"><figcaption><strong>{e(c["file"])}</strong> — {e(c["origin"])}. Capture Chromium brute, sans retouche ni génération. Les plans du Codex sont distincts.</figcaption></figure>'
body='<p class="eyebrow">ALIENS / V110 — rapport local de livraison</p><h1>Tenir les accès</h1><p class="lead">Une porte fermée n’arrête plus indéfiniment une piste. Le groupe peut récupérer trois plaques, souder un battant, puis choisir quand le découper ou le refaire.</p>'+metrics([(passed,'tests Node réussis'),(len(B['tests']),'contrôles navigateur'),(5,'opérations complètes'),(len(B['captures']),'captures directes de Chromium')])
body+='<nav><a href="JOUER_ALIENS_V110.html">Jouer</a><a href="CODEX_LEVEL_DESIGN_V110.html">Codex</a><a href="#preuves">Preuves</a><a href="#limites">Limites</a></nav><div class="callout">Branche autonome V109 poursuivie, pas une fusion native Tantalus. Les images embarquées sont les octets exacts des PNG du navigateur. Les étapes tardives utilisent des exports non modifiés de parcours, puis les manœuvres et le temps indiqués sont exécutés par la vraie interface. Aucun hook d’édition de partie n’est ajouté à la page.</div>'
body+='<h2>Ce qui change dans l’opération</h2><p>Huit battants partagés conservent intégrité et renfort. Le Warrior rejoint la face, prépare son coup, puis retire la protection avant l’intégrité. Une brèche ouvre les deux côtés du raccord. Ce n’est ni un nouvel ennemi ni une modification d’objectif : la menace qui a suivi la fuite garde sa vie et son identité.</p><p>Le stock de maintenance fournit trois plaques après ouverture. Renforcer et refaire un battant coûtent chacun une plaque ; découper ouvre sans remboursement. Déplacement, tir ou impact interrompent le travail avant tout débit. Les deux faces du seuil doivent être libres lors d’une reconstruction.</p>'
for file,title in selection:body+=picture(byfile[file],title)
body+='<h2 id="preuves">Ce que la recette établit</h2>'+table(['Domaine','Résultat','Méthode'],[['Node',f'{passed} réussis','260 historiques réexécutés + 83 nouveaux invariants V110'],['Chromium',f'{len(B["tests"])} réussis','Sept recettes : 103 contrôles hérités + génie'],['Parcours complets','5 terminés','Direct, service, deux boucles logistiques, opération de brèche'],['Poursuite distincte',str(P.get('transfers',P.get('enemyTransfers',2)))+' franchissements','Exercice de fuite hérité rejoué'],['Captures',str(len(B['captures']))+' PNG',str(len(selection))+' embarqués, provenance par fichier']])
rows=[]
for v in D['results']+L['results']:
 team=v.get('team',v.get('ammunition'));rip=next(a for a in team if a['id']=='ripley');rows.append([v['variant'],'terminé' if v['complete'] else 'échec',v['inputs'],f'{v["elapsed"]:.2f}',f'{rip["hp"]} PV / {rip["ammo"]} coups'])
rip=next(a for a in H['team'] if a['id']=='ripley');rows.append(['brèche / réfection / repli','terminé' if H['complete'] else 'échec',H['inputs'],f'{H["elapsed"]:.2f}',f'{rip["hp"]} PV / {rip["ammo"]} coups'])
body+=table(['Parcours','État','Entrées / sous-pas','Secondes simulées','Ripley finale'],rows)+'<p class="small">Les temps simulés ne sont pas des durées de jeu humaines. Les pilotes lisent le chemin calculé mais n’écrivent ni positions, vies, munitions, réserves, mémoires ou objectifs. Ils utilisent mouvement, tir, interaction, ordres et progression du temps.</p>'
h=H['engineering'];m=h['metrics'];body+='<h3>Le parcours de brèche, en particulier</h3><p>Départ à l’insertion normale, fuite sans éliminer la paire de Hadley, fermeture du sas, quatre impacts, rupture puis franchissement. Le groupe retourne chercher le kit, répare, soude, découpe et termine les étapes de Newt et de défense. Des exports sont rechargés après le premier choc et au milieu du travail.</p>'+table(['Plaques finales','Dépensées','Impacts','Brèches','Renforts','Réfections','Découpes'],[[h['plates'],h['spent'],m['enemyHits'],m['breaches'],m['reinforced'],m['repaired'],m['cut']]])
body+='<h2>Corrections et contrôles utiles</h2><p>La dépendance entre bruit et génie est liée explicitement une seule fois : le chargeur Blob reste sans cycle de modules. Un frappeur ignore son propre bruit pour ne pas effacer la piste qu’il poursuit. Le système de pression est réservé aux Warriors. Les actions préparées expirent ou sont annulées lorsque leur cible n’est plus valable.</p><p>Sur 844 × 390, ajouter une bande permanente avait réduit la zone de jeu sous la taille minimale déjà testée. La correction partage un seul emplacement Réserves / Génie, sans réduire l’exigence de recette. Les contrôles attendent l’initialisation des modules avant de compter les inspections ; aucune donnée de jeu n’est injectée pour produire les captures.</p>'
body+='<h2 id="limites">Portée réelle</h2><p>Aucune salle, aucun ennemi ni objectif obligatoire supplémentaire. Aucun raccord natif aux 64 salles, push GitHub ou déploiement Vercel. Les tirs restent dans leur pièce, les transferts sont discrets et les contacts simulent seulement le réseau d’opération. Les Facehuggers ne percent pas les battants ; les portes intérieures et le final Sulaco gardent leurs systèmes précédents. Une plaque est une ressource collective sans poids ; pas de production, récupération ou recyclage.</p><p>Le rendu reste procédural stylisé ; la nouvelle pose de travail et ses effets ne constituent pas un pack de sprites d’acteurs finalisés. L’import vérifie cohérence et comptes, ce n’est pas un anti-triche signé. Les écrans tactiles sont émulés ; aucune manette, téléphone physique ou configuration GPU cible n’est certifiée.</p>'
body+='<h2>Provenance et reproduction</h2><p class="mono">Archive source : '+e(PROV['archive'])+'<br>SHA-256 : '+e(PROV['sha256'])+'<br>HTML soumis au navigateur : '+e(B['htmlSha256'])+'<br>Contrat : '+e(C['contract'])+'</p><p>'+e(PROV['count'])+' sources et tests hérités comparés octet pour octet à la V109. Les preuves historiques restent dans leurs dossiers ; les nouveaux résultats sont suffixés v110. Le vérificateur du paquet est strictement en lecture seule.</p>'
(R/'RAPPORT_ILLUSTRE_V110.html').write_text(page('Aliens V110 — Rapport illustré Tenir les accès',body))
(R/'report/report-selection-v110.json').write_text(json.dumps({'captured':len(B['captures']),'embedded':len(selection),'rules':len(RULES),'files':[s[0] for s in selection],'rawImageBytesUnchanged':True},ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'codexRooms':len(C['rooms']),'rules':len(RULES),'reportImages':len(selection),'browserCaptures':len(B['captures'])},indent=2))
